//! Copies the fallback chain generated by Nix into `OUT_DIR`.
//!
//! The chain is declared in `nix/fontconfig.nix` — the one place that also
//! writes fontconfig's `.conf`, so that the renderer and the foreign apps
//! cannot disagree about which face draws a script — and turned into Rust by
//! `nix/scripts/gen-chain.py`. This build script does NOT generate it; it only
//! locates the finished file. Generating here would reimplement Nix logic
//! (invariant 5) and would give the chain a second author.
//!
//! It is the same shape as `ronoctua-tokens`, deliberately: whoever has read
//! that one has read this one.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_CHAIN_RS");

    let generated = env::var("RONOCTUA_CHAIN_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_CHAIN_RS is not set.\n\
             \n\
             The fallback chain is generated by Nix out of nix/fontconfig.nix.\n\
             Enter the environment with `direnv allow` (or `nix develop`), which sets\n\
             the variable, or build through the flake with `nix build`.\n\
             \n\
             Generating the chain here would reimplement Nix logic (invariant 5)."
        )
    });

    println!("cargo:rerun-if-changed={generated}");

    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("chain.rs");
    // DELETE FIRST — the file comes from the store read-only, and `fs::copy`
    // inherits the mode along with the content. See `ronoctua-tokens/build.rs`.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
